#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Deploys the app to AWS Lightsail behind a Cloudflare Tunnel: docs/DEPLOY.md, steps 1–8.
# Run from anywhere in the repo: scripts/deploy-wizard.sh
# Re-running is safe: stages already done offer to skip, and values already captured are kept.

# already "thing": y skips a stage the human finished on an earlier run.
already() { confirm "Already done: $1? (y skips this stage)"; }

# run "command": shows the command, runs it, and on failure offers a retry or a stop.
run() {
  printf '  %s$ %s%s\n' "$DIM" "$1" "$RESET"
  until bash -c "$1"; do
    warn "that failed."
    [[ -n "${2:-}" ]] && note "$2"
    confirm "Try again?" || { warn "Stopped. Fix it and re-run: finished stages offer to skip."; exit 1; }
  done
}

# laptop_bots_stopped: waits until no `offer-engine start` runs on this laptop.
laptop_bots_stopped() {
  while pgrep -f "offer-engine start" >/dev/null; do
    warn "offer-engine start is running on this laptop. Only one process may poll each bot token."
    pause "Stop it (Ctrl-C in its terminal), then press Enter"
  done
}

run_wizard() {

TOTAL_STAGES=13
cd "$(git rev-parse --show-toplevel)"
# The instance's .env, built on the laptop. Gitignored and dockerignored by the `.env.*` rule.
ENV_FILE=.env.poe

banner "Deploy the Personalised Offer Engine"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight: the laptop side"
say "Checks the laptop has what the deploy needs. Nothing changes yet."
missing=()
for tool in git ssh scp tar uv; do command -v "$tool" >/dev/null || missing+=("$tool"); done
if (( ${#missing[@]} )); then warn "missing: ${missing[*]}. Install them and re-run."; exit 1; fi
[[ -f .env ]] || { warn "no .env here. Run 'uv run offer-engine setup' first."; exit 1; }
for db in data/offer_engine.db data/demo.db; do
  [[ -f "$db" ]] || { warn "$db is missing. Build the world and run 'offer-engine demo snapshot' first."; exit 1; }
done
step "Keys in .env (values hidden):"
uv run --quiet offer-engine check-env | sed 's/^/      /' \
  || warn "check-env reports missing keys. Fix .env before stage 10 copies it up."
step "This deploy ships commit $(git log -1 --format='%h %s') (branch $(git branch --show-current))."
[[ -z "$(git status --porcelain)" ]] \
  || warn "You have uncommitted changes. They will NOT be deployed: git archive ships HEAD only."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Anthropic: cap Claude spend at \$100 a month"
say "Both web pages are open, with no password (QnA Q61). The spend cap is what limits misuse."
if ! already "the \$100 monthly limit is set"; then
  open_url "https://console.anthropic.com/settings/limits"
  step "Sign in with the account that owns ANTHROPIC_API_KEY."
  step "Not sure which workspace owns the key? Settings › API keys lists each key's workspace."
  step "Set a \$100 monthly spend limit on that workspace: Settings › Workspaces › <workspace> › Limits."
  step "If the organisation has only the Default workspace, set it under Settings › Limits instead."
  step "Save."
  pause "Press Enter once the limit shows \$100"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Lightsail: create the instance"
if ! already "the Lightsail instance exists and is Running"; then
  open_url "https://lightsail.aws.amazon.com/ls/webapp/home/instances"
  step "Sign in with the AWS account that holds the credits. Click 'Create instance'."
  step "Instance location: 'Change AWS Region and Availability Zone' › Mumbai (ap-south-1). Any zone."
  step "Platform: Linux/Unix. Blueprint: 'Operating System (OS) only' › Ubuntu 24.04 LTS."
  step "SSH key pair: either keep Lightsail's default and click 'Download' (a .pem file),"
  say  "    or 'Change SSH key pair' › Upload your own public key (e.g. ~/.ssh/id_ed25519.pub)."
  step "Network type: Dual-stack (IPv4 and IPv6)."
  step "Plan: General purpose, \$12 USD a month: 2 GB memory, 2 vCPUs."
  step "Name it offer-engine. Click 'Create instance'."
  step "Wait for the instance card to say Running (about a minute)."
  note "Cost: about \$12 a month, paid from AWS credits."
  pause "Press Enter once it says Running"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Lightsail: firewall and IP address"
say "Nothing needs to reach the instance except SSH: the bots poll Telegram and the tunnel connects out."
if ! already "HTTP (80) is deleted and only SSH (22) is left"; then
  step "Click the offer-engine instance, then the Networking tab."
  step "IPv4 Firewall: delete the HTTP · TCP · 80 rule (trash icon). Keep SSH · TCP · 22."
  step "Further down, if there's an IPv6 Firewall with an HTTP · TCP · 80 rule, delete it too. No such rule: skip."
  note "Nothing listens on port 80 anyway (compose publishes no port), so this is tidying, not a hole."
  note "Optional: 'Attach static IP' on the same tab (free while attached) keeps the IP the same"
  note "across a stop and start. Without it, a restart changes the IP and the next stage's alias."
  pause "Press Enter once only SSH (22) is left"
fi
say ""
say "Keep this tab open: the next stage asks for the Public IPv4 address shown at the top of it."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "SSH: the poe alias"
say "Every command from here on reaches the instance as 'ssh poe'."
current_host=$(ssh -G poe 2>/dev/null | awk '/^hostname /{print $2}' || true)
if [[ -n "$current_host" && "$current_host" != "poe" ]]; then
  step "~/.ssh/config already has Host poe → $current_host."
  note "If the instance's IP changed, edit that HostName line by hand, then press Enter."
  pause
else
  ask POE_IP "Public IPv4 address of the instance:"
  say "The private key: Lightsail's default one you downloaded (e.g. ~/Downloads/LightsailDefaultKey-ap-south-1.pem),"
  say "or your own (e.g. ~/.ssh/id_ed25519) if you uploaded its .pub."
  key=""
  until [[ -f "$key" ]]; do
    ask POE_KEY "Path to the private key:"
    key="${POE_KEY/#\~/$HOME}"
    [[ -f "$key" ]] || warn "no file at $key"
  done
  chmod 600 "$key"
  say ""
  say "This block goes at the end of ~/.ssh/config:"
  block=$'\n'"Host poe"$'\n'"  HostName $POE_IP"$'\n'"  User ubuntu"$'\n'"  IdentityFile $key"$'\n'"  IdentitiesOnly yes"$'\n'
  printf '%s%s%s\n' "$DIM" "$block" "$RESET"
  if confirm "Add it?"; then
    mkdir -p ~/.ssh && chmod 700 ~/.ssh
    printf '%s' "$block" >> ~/.ssh/config
    chmod 600 ~/.ssh/config
    printf '  %s✓ added%s Host poe to ~/.ssh/config\n' "$GREEN" "$RESET"
  else
    pause "Add it yourself, then press Enter"
  fi
fi
say "Testing the connection (the first time accepts the instance's host key)…"
run "ssh -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 -n poe true" \
  "Check the IP, the key path, and that the Lightsail firewall still allows SSH (22)."
printf '  %s✓ ssh poe works%s\n' "$GREEN" "$RESET"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Instance: install Docker"
if ssh -n poe 'docker info >/dev/null 2>&1 && docker compose version' >/dev/null 2>&1; then
  printf '  %s✓ Docker and Compose already work for user ubuntu. Skipping.%s\n' "$GREEN" "$RESET"
else
  say "Installs Docker from get.docker.com (about a minute) and adds user ubuntu to the docker group."
  confirm "Install Docker on the instance now?" || { warn "Docker is needed. Re-run when ready."; exit 1; }
  run "ssh -n poe 'curl -fsSL https://get.docker.com | sudo sh && sudo usermod -aG docker ubuntu'"
  say "Checking from a fresh login, so the group change applies…"
  run "ssh -n poe 'docker info >/dev/null && docker compose version'" \
    "If the error says 'permission denied' on docker.sock, an ssh ControlMaster may be reusing the old login: run 'ssh -O exit poe'."
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: create the tunnel"
warn "uselattice.app also hosts Lattice. Don't touch any other DNS record or any zone-wide"
warn "setting (SSL/TLS mode, WAF, rules, cache): they apply to Lattice too."
say ""
if ! already "the offer-engine tunnel exists"; then
  open_url "https://one.dash.cloudflare.com/"
  step "Pick the account that owns uselattice.app."
  step "Networks › Tunnels › 'Create a tunnel' › Cloudflared."
  step "Name it offer-engine. Save tunnel."
  step "On 'Install and run a connector', pick Docker. The command ends in '--token eyJ…'."
else
  step "Open Zero Trust › Networks › Tunnels › offer-engine › Configure (or Edit):"
  step "the Overview shows the install command again, ending in '--token eyJ…'."
fi
step "Copy only the token: the long string after --token. Don't run the command; compose runs the connector."
TUNNEL_TOKEN=""
until [[ "$TUNNEL_TOKEN" == eyJ* ]]; do
  ask_secret TUNNEL_TOKEN "Paste the tunnel token:"
  [[ "$TUNNEL_TOKEN" == eyJ* ]] || warn "a tunnel token starts with eyJ. Copy just the part after --token."
done
write_env TUNNEL_TOKEN "$TUNNEL_TOKEN"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: public hostnames"
say "Two routes from the tunnel to the app. 'app' is the compose service name: the tunnel container"
say "reaches it over compose's network, so the instance opens no web port."
if ! already "both hostnames are added"; then
  step "Click Next on the connector page, or open the tunnel › 'Public Hostname' tab"
  say  "    (newer dashboards: 'Published application routes') › 'Add a public hostname'."
  step "First:   Subdomain offers          Domain uselattice.app   Path empty   Type HTTP   URL app:8502"
  step "Save. Add a second one:"
  step "Second:  Subdomain offers-console  Domain uselattice.app   Path empty   Type HTTP   URL app:8501"
  step "Save."
  warn "Type is HTTP, not HTTPS: Cloudflare adds HTTPS at its edge."
  warn "If Cloudflare says a DNS record for either name already exists, stop: don't overwrite a record you didn't make."
  note "One-level subdomains only: the free certificate covers *.uselattice.app, not *.offers.uselattice.app."
  pause "Press Enter once both are saved"
fi
step "Check: uselattice.app › DNS › Records shows two new CNAMEs, offers and offers-console,"
say  "    pointing at <id>.cfargotunnel.com, and nothing else changed."
note "The tunnel shows Inactive or Down until stage 12 starts it. That's expected."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Instance: copy the code"
say "Ships commit $(git log -1 --format='%h %s') to ~/offer-engine on the instance."
note "Only committed files go, so the instance needs no GitHub access."
note "Re-running overwrites the code and never touches data/."
if confirm "Copy the code now?"; then
  run "ssh -n poe 'mkdir -p offer-engine/data'"
  run "git archive HEAD | ssh poe 'tar -x -C offer-engine'"
  printf '  %s✓ code copied%s\n' "$GREEN" "$RESET"
else
  warn "Skipped. Stage 10 needs ~/offer-engine to exist."
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Instance: write its .env"
say "Builds $ENV_FILE here (gitignored, mode 600): your .env plus the deploy settings below."
say "Then copies it to the instance as offer-engine/.env."
(umask 077 && grep -vE '^(TUNNEL_TOKEN|AGENT_MODE|DEMO_SEED|CONSOLE_PASSWORD|DB_PATH)=' .env > "$ENV_FILE" || true)
write_env TUNNEL_TOKEN "$TUNNEL_TOKEN"
write_env AGENT_MODE replay
write_env DEMO_SEED 7
write_env CONSOLE_PASSWORD ""
write_env DB_PATH ""
say ""
note "AGENT_MODE=replay: demo scenarios replay recordings; Claude is called only for a missing answer."
note "DEMO_SEED=7: repeatable Offer codes in the demo."
note "CONSOLE_PASSWORD empty: both pages are open. To add one later, set it in the instance's .env"
note "    and run: ssh poe 'cd offer-engine && docker compose up -d'"
note "DB_PATH empty: the app uses data/offer_engine.db inside the mounted folder."
say ""
step "Keys in $ENV_FILE: $(grep -oE '^[A-Z_]+' "$ENV_FILE" | paste -sd' ' -)"
if confirm "Copy it to the instance as offer-engine/.env (replaces any existing one)?"; then
  run "scp -q $ENV_FILE poe:offer-engine/.env && ssh -n poe 'chmod 600 offer-engine/.env'"
  printf '  %s✓ instance .env written%s\n' "$GREEN" "$RESET"
else
  warn "Skipped. Compose won't start without TUNNEL_TOKEN in the instance's .env."
fi
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Instance: copy the databases"
say "Copies data/offer_engine.db (the world, the Decision log, chat links) and data/demo.db (the demo"
say "snapshot). Telegram chat IDs are the same whichever machine runs the bots, so chat links carry over."
laptop_bots_stopped
while compgen -G "data/*.db-wal" >/dev/null; do
  warn "Left over: $(echo data/*.db-wal). Something still has the database open (a console, a test run?)."
  note "SQLite folds the -wal file into the database when the last connection closes."
  pause "Close it, then press Enter"
done
printf '  %s✓ laptop bots stopped, no -wal files left%s\n' "$GREEN" "$RESET"
copy_dbs=1
if ssh -n poe 'test -f offer-engine/data/offer_engine.db'; then
  warn "The instance already has a database. Copying replaces it: whatever evaluators did there is lost."
  confirm "Replace the instance's databases with the laptop's?" || copy_dbs=0
fi
if (( copy_dbs )); then
  tgz="$(mktemp -d)/poe-data.tgz"
  # Stop the app first so nothing writes while the files are replaced; a clean stop leaves no -wal.
  run "ssh -n poe 'cd offer-engine && docker compose stop app >/dev/null 2>&1; rm -f data/*.db-wal data/*.db-shm'"
  run "tar -czf $tgz -C data offer_engine.db demo.db"
  run "scp -q $tgz poe:poe-data.tgz"
  run "ssh -n poe 'tar -xzf poe-data.tgz -C offer-engine/data && rm poe-data.tgz'"
  rm -rf "$(dirname "$tgz")"
  printf '  %s✓ databases copied%s\n' "$GREEN" "$RESET"
else
  note "Kept the instance's databases."
fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Instance: start"
say "Only one process may poll each bot token: the laptop's bots stay stopped while the instance runs."
laptop_bots_stopped
confirm "Build and start the containers now? (the first build takes a few minutes)" \
  || { warn "Not started. Re-run when ready."; exit 1; }
run "ssh -n poe 'cd offer-engine && docker compose up -d --build'"
say ""
say "Waiting for the app and the tunnel to come up (up to 2 minutes)…"
printf '  '
up=0
for _ in $(seq 1 24); do
  running=$(ssh -n poe 'cd offer-engine && docker compose ps --status running --services' 2>/dev/null || true)
  logs=$(ssh -n poe 'cd offer-engine && docker compose logs --no-color' 2>/dev/null || true)
  if grep -qE "exited with code [1-9]" <<<"$logs"; then break; fi
  if grep -qx app <<<"$running" && grep -qx tunnel <<<"$running" \
     && grep -q "Registered tunnel connection" <<<"$logs"; then up=1; break; fi
  printf '.'; sleep 5
done
printf '\n'
ssh -n poe 'cd offer-engine && docker compose logs --no-color --tail 15' 2>/dev/null | sed 's/^/    /' || true
if (( up )); then
  printf '\n  %s✓ app running, tunnel registered%s\n' "$GREEN" "$RESET"
else
  warn "Not up yet. Read the log above. Follow it with: ssh poe 'cd offer-engine && docker compose logs -f'"
  SKIPPED+=("containers didn't come up cleanly: check 'docker compose logs' on the instance")
fi
note "Expect lines prefixed [offer-bot], [customer-bots], [console] and [live] as they print,"
note "and the tunnel's 'Registered tunnel connection' lines."
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Check it end to end"
bot=$(grep -E '^OFFER_BOT_USERNAME=' .env | tail -n1 | cut -d= -f2- | tr -d "'\"")
step "On your phone, open https://t.me/$bot (or search @$bot in Telegram)."
step "Send /start: the Persona buttons arrive. Tap one, then send /offers: an Offer Card arrives."
confirm "Did the Persona buttons and an Offer Card arrive?" \
  || SKIPPED+=("Offer Bot: is the laptop's bot stopped? Check ssh poe 'cd offer-engine && docker compose logs app'")
say ""
open_url "https://offers.uselattice.app"
step "Live engine view: press Reset, then run a scenario. Its Decision plays back."
confirm "Did the Decision play back?" \
  || SKIPPED+=("Live view: tunnel Healthy in Cloudflare? Route offers → HTTP app:8502? A new hostname's certificate can take a few minutes")
say ""
open_url "https://offers-console.uselattice.app"
step "Console: the Decision log loads."
confirm "Did the Decision log load?" \
  || SKIPPED+=("Console: route offers-console → HTTP app:8501? Check the [console] lines in the app log")

finish
printf '%s%s  Day to day%s\n' "$BOLD" "$BLUE" "$RESET"
note "Redeploy a commit:  git archive HEAD | ssh poe 'tar -x -C offer-engine'"
note "                    ssh poe 'cd offer-engine && docker compose up -d --build'"
note "Follow logs:        ssh poe 'cd offer-engine && docker compose logs -f app'"
note "Reset the demo:     the live page's Reset button"
note "Any CLI command:    ssh poe 'cd offer-engine && docker compose exec app uv run --no-sync offer-engine <command>'"
note "Memory use:         ssh poe 'docker stats --no-stream'"
note "Stop:               ssh poe 'cd offer-engine && docker compose down'"
note "Bots on the laptop: ssh poe 'cd offer-engine && docker compose stop app' first"
say ""
note "After judging: delete the Lightsail instance, then in Cloudflare the offer-engine tunnel"
note "and the offers and offers-console DNS records. More in docs/DEPLOY.md."
printf '\n'
}

run_wizard "$@"; exit
